; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: ti89 (TI-89 / 92+ / V200 (68000, AMS)), starts in turbo mode
; ============================================================

			org 0

;## ntc_md_vectors ntc_ti89_boot
; (the 68k backend requires this section be named ntc_md_vectors - the generic
;  "68k start" slot. On AMS there is no program-owned vector table; this is just
;  the entry. ;!!TI89? the real AMS nostub header/reloc goes here - stubbed.)
			bra ntc_ti89_boot

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; main.bas 18: Print "Lists on "; System.Platform
			dc.l kw_printstrvar, str1
			dc.l kw_printnl

			; main.bas 19: h = List.Create(4)
			dc.l kw_l_mov, llit_0, var_h

			; main.bas 20: seed = 12345
			dc.l kw_ltov, 12345, var_seed

			; main.bas 21: For i = 1 To 500
			dc.l kw_ltov, 1, var_i
for1_t:

			; main.bas 22: n = List.Append(h)
			dc.l kw_l_mov, llit_0, var_n

			; main.bas 23: If n = 0 Then Print "No room after"; i - 1 : Exit For
			dc.l kw_l_cpeq, var_n, llit_0
			dc.l kw_goto_iffalse, if2_1
			dc.l kw_addl, var_i, -1, tmp0
			dc.l kw_printstrvar, str2
			dc.l kw_printint, tmp0
			dc.l kw_printnl
			dc.l for1_e_go
if2_1:

			; main.bas 24: seed = (seed * 75 + 74) And &H7FFF       ' a small random number generator
			dc.l kw_mulvl, var_seed, 75, tmp0
			dc.l kw_addl, tmp0, 74, tmp0
			dc.l kw_andvl, tmp0, 32767, var_seed

			; main.bas 25: List.SetWord n, ID, i

			; main.bas 26: List.SetWord n, SCORE, seed Mod 10000

			; main.bas 27: Next
			dc.l kw_next1l, var_i, 500, for1_t
for1_e:

			; main.bas 28: Print List.Count(h); " players"
			dc.l kw_printstrvar, str3
			dc.l kw_printnl

			; main.bas 30: r = List.Sort(h, SCORE)
			dc.l kw_ztov, var_r

			; main.bas 31: Print "Top 5:"
			dc.l kw_printstrvar, str4
			dc.l kw_printnl

			; main.bas 32: n = List.Last(h)
			dc.l kw_l_mov, llit_0, var_n

			; main.bas 33: For i = 1 To 5
			dc.l kw_ltov, 1, var_i
for3_t:

			; main.bas 34: Print "  player "; List.GetWord(n, ID); ": "; List.GetWord(n, SCORE)
			dc.l kw_printstrvar, str5
			dc.l kw_printnl

			; main.bas 35: n = List.PrevOf(n)
			dc.l kw_l_mov, llit_0, var_n

			; main.bas 36: Next
			dc.l kw_next1l, var_i, 5, for3_t
for3_e:

			; main.bas 39: n = List.First(h)
			dc.l kw_l_mov, llit_0, var_n

			; main.bas 40: Do While n <> 0
do4_t:
			dc.l kw_l_cpne, var_n, llit_0
			dc.l kw_goto_iffalse, do4_e

			; main.bas 41: nxt = List.NextOf(n)
			dc.l kw_l_mov, llit_0, var_nxt

			; main.bas 42: If List.GetWord(n, SCORE) < 5000 Then r = List.Delete(h, n)
			dc.l kw_ztov, var_r
if5_1:

			; main.bas 43: n = nxt
			dc.l kw_l_mov, var_nxt, var_n

			; main.bas 44: Loop
			dc.l do4_t_go
do4_e:

			; main.bas 45: Print List.Count(h); " players with 5000 or more"
			dc.l kw_printstrvar, str6
			dc.l kw_printnl

			; main.bas 46: n = List.Search(h, ID, 250)
			dc.l kw_l_mov, llit_0, var_n

			; main.bas 47: If n <> 0 Then Print "Player 250 scored "; List.GetWord(n, SCORE) Else Print "Player 250 is gone"
			dc.l kw_l_cpne, var_n, llit_0
			dc.l kw_goto_iffalse, if6_1
			dc.l kw_printstrvar, str7
			dc.l kw_printnl
			dc.l if6_e_go
if6_1:
			dc.l kw_printstrvar, str8
			dc.l kw_printnl
if6_e:

			; main.bas 48: r = List.Destroy(h)
			dc.l kw_ztov, var_r

			; main.bas 50: End
			dc.l kw_printnl0
			dc.l kw_printstrvar, str9
			dc.l kw_waitkey
			dc.l kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

for1_e_go:			lea for1_e, sp
			rts
do4_t_go:			lea do4_t, sp
			rts
if6_e_go:			lea if6_e, sp
			rts

; ============================================================
; Variables
; ============================================================

; (68000: in the RAM block at the end, from $FF8000)

; numbers passed by address (read only)
			even
ntc_aptab:		dc.l 0		; AddressOf: the procedures CallAddr runs, by number
llit_0:			dc.l 0

; ============================================================
; Strings
; ============================================================

str0:			dc.b "TI89", 0
str1:			dc.b "Lists on TI89", 0
str2:			dc.b "No room after", 0
str3:			dc.b "0 players", 0
str4:			dc.b "Top 5:", 0
str5:			dc.b "  player 0: 0", 0
str6:			dc.b "0 players with 5000 or more", 0
str7:			dc.b "Player 250 scored 0", 0
str8:			dc.b "Player 250 is gone", 0
str9:			dc.b "Press a key", 0
str10:			dc.b 0
			even

; ============================================================
; Keyword library (used)
; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			addq.w #1, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			bge ntc_for_take		; limit >= var
			addq.l #4, sp
			rts

			even
;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			add.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvl
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			muls.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_andvl
kw_andvl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			and.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## kw_l_mov
kw_l_mov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), (a1)
			rts

			even
;## ntc_lcmp
; tails: d0 = a (long), d1 = b: Z if a <rel> b
ntc_lcmp_lt:
			cmp.l d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_lcmp_le:
			cmp.l d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_lcmp_gt:
			cmp.l d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_lcmp_ge:
			cmp.l d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_lcmp_ne:
			cmp.l d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_l_cpeq
kw_l_cpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			cmp.l (a1), d0
			rts

			even
;## kw_l_cpne ntc_lcmp
kw_l_cpne:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			bra ntc_lcmp_ne

			even
;## ntc_ti89_boot ntc_plat_data ntc_data ntc_plat_screen
ntc_ti89_boot:
			; AMS entered us in user mode with a valid stack; clear the screen
			; and hand control to the thread (the compiler's start code follows,
			; sets A7 to the thread and runs).
			jsr ntc_ti89_clear
			rts

			even
;## ntc_plat_data ntc_data
; ------------------------------------------------------------
; UNVERIFIED hardware values - every one is a guess.  ;!!TI89? confirm all.
; ------------------------------------------------------------
LCD_MEM     equ $4C00           ; LCD bitmap base in RAM          ;!!TI89? guess
ROWBYTES    equ 30              ; bytes per pixel row (240/8; the 89 is 20) ;!!TI89?
SCRROWS     equ 128             ; pixel rows (the 89 is 100)       ;!!TI89?

ntc_curx:   dc.w 0              ; text column (0..cols-1)
ntc_cury:   dc.w 0              ; text row (0..rows-1)
ntc_frames: dc.w 0              ; frame counter (ntc_plat_ticks)

			even
;## ntc_plat_screen ntc_plat_data ntc_data
; platform routines: entered with jsr, end with rts (real stack), keeping
; d2-d7 / a2-a6 (the 68k backend's convention).

; ntc_ti89_celladdr - a0 = LCD byte address of the top row of cell (curx,cury).
; addr = LCD_MEM + cury*8*ROWBYTES + curx   (8px-wide font = 1 byte per column)
ntc_ti89_celladdr:
			move.w ntc_cury, d1
			lsl.w #3, d1               ; row * 8 pixel rows
			mulu #ROWBYTES, d1
			add.w ntc_curx, d1
			lea LCD_MEM, a0
			adda.w d1, a0
			rts

; ntc_plat_putc - d0.b = character 32..127: blit its 8x8 glyph, advance
ntc_plat_putc:
			and.w #$00FF, d0
			sub.w #32, d0
			bge.s ntc_pc_ok
			moveq #0, d0               ; below space -> space
ntc_pc_ok:
			lsl.w #3, d0               ; glyph = font + char*8
			lea ntc_ti89_font, a1
			adda.w d0, a1
			jsr ntc_ti89_celladdr
			moveq #7, d2               ; 8 rows
ntc_pc_row:
			move.b (a1)+, (a0)
			adda.w #ROWBYTES, a0
			dbra d2, ntc_pc_row
			addq.w #1, ntc_curx
			cmp.w #30, ntc_curx        ; cols ;!!TI89? (89 = 20)
			blt.s ntc_pc_done
			jsr ntc_plat_newline
ntc_pc_done:
			rts

; ntc_plat_newline - column 0, next row; scroll not done yet ;!!TI89? scroll
ntc_plat_newline:
			clr.w ntc_curx
			addq.w #1, ntc_cury
			cmp.w #16, ntc_cury        ; rows ;!!TI89? (89 = 12)
			blt.s ntc_nl_done
			move.w #15, ntc_cury
ntc_nl_done:
			rts

; ntc_ti89_clear - blank the whole LCD bitmap
ntc_ti89_clear:
			lea LCD_MEM, a0
			move.w #ROWBYTES*SCRROWS-1, d1
ntc_cl_lp:
			clr.b (a0)+
			dbra d1, ntc_cl_lp
			clr.w ntc_curx
			clr.w ntc_cury
			rts

			even
;## ntc_plat_key ntc_plat_data ntc_data
; ntc_plat_scankey - d0.b = a key or 0.  ;!!TI89? the 68k calc key matrix is a
; memory-mapped port read (row strobe / column read); the exact addresses were
; NOT grounded, so this is a stub returning "no key". Wire the port + a code
; map before Inkey works. (An AMS build would ROM_CALL ngetchx instead.)
ntc_plat_scankey:
			moveq #0, d0               ; ;!!TI89? no key matrix read yet
			rts

; ntc_plat_getkey - wait for a key (spins on the stub above until wired)
ntc_plat_getkey:
			jsr ntc_plat_scankey
			tst.b d0
			beq.s ntc_plat_getkey
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - return to AMS. ;!!TI89? a nostub program returns with rts to
; the kernel; this restores nothing special yet.
ntc_plat_exit:
			rts


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $FF8000
ntc_ram:
; variables
var_h:			dc.l 0
var_seed:			dc.w 0
var_i:			dc.w 0
var_n:			dc.l 0
var_r:			dc.w 0
var_nxt:			dc.l 0
tmp0:			dc.w 0
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
